application.css:
:root {
  --ink: #172033;
  --muted: #6e7890;
  --line: #e5e9f1;
  --purple: #6558d8;
  --purple-dark: #5045bc;
  --soft: #f4f3ff;
  --green: #159570;
}
* { box-sizing: border-box; }
body {
  margin: 0;
  min-height: 100vh;
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  color: var(--ink);
  background: radial-gradient(circle at 8% 12%, #e9e7ff 0, transparent 32%), linear-gradient(135deg, #f8f9fc, #eef1f8);
}
.page-shell { width: min(920px, calc(100% - 32px)); margin: 0 auto; padding: 58px 0 26px; }
.quiz-card { background: rgba(255,255,255,.94); border: 1px solid rgba(255,255,255,.8); border-radius: 24px; box-shadow: 0 20px 55px rgba(44, 51, 86, .12); overflow: hidden; }
.quiz-header { padding: 38px 42px 30px; border-bottom: 1px solid var(--line); }
.eyebrow { color: var(--purple); font-size: .72rem; font-weight: 800; letter-spacing: .14em; text-transform: uppercase; }
h1 { margin: 10px 0 8px; font-size: clamp(2rem, 5vw, 3.1rem); letter-spacing: -.05em; }
.quiz-header p { margin: 0; color: var(--muted); line-height: 1.6; }
.questions { padding: 8px 42px 12px; }
.question { border: 0; border-bottom: 1px solid var(--line); padding: 26px 0 30px; margin: 0; min-width: 0; }
.question:last-child { border-bottom: 0; }
legend { display: flex; gap: 15px; align-items: center; width: 100%; padding: 0; font-size: 1.08rem; font-weight: 700; }
.question-number { display: grid; place-items: center; width: 34px; height: 34px; flex: 0 0 34px; color: var(--purple); background: var(--soft); border-radius: 10px; font-size: .72rem; }
.options { display: grid; grid-template-columns: repeat(3, 1fr); gap: 11px; margin: 20px 0 0 49px; }
.option { display: flex; align-items: center; min-height: 48px; padding: 11px 14px; border: 1px solid var(--line); border-radius: 11px; color: #4d5870; cursor: pointer; transition: .18s ease; }
.option:hover { border-color: #aaa3ee; background: #faf9ff; transform: translateY(-1px); }
.option:has(input:checked) { border-color: var(--purple); background: var(--soft); color: var(--purple-dark); font-weight: 700; box-shadow: 0 4px 12px rgba(101,88,216,.1); }
.option input { position: absolute; opacity: 0; pointer-events: none; }
.custom-radio { width: 16px; height: 16px; margin-right: 9px; border: 2px solid #c9cfdb; border-radius: 50%; background: white; }
.option:has(input:checked) .custom-radio { border: 5px solid var(--purple); }
.actions { display: flex; align-items: center; justify-content: space-between; gap: 20px; padding: 25px 42px 28px; background: #fbfbfe; }
button { border: 0; border-radius: 12px; padding: 14px 21px; color: white; background: var(--purple); font: inherit; font-weight: 750; cursor: pointer; box-shadow: 0 7px 15px rgba(101,88,216,.25); transition: .18s ease; }
button:hover { background: var(--purple-dark); transform: translateY(-2px); }
button span { margin-left: 12px; font-size: 1.15rem; }
.result { display: flex; align-items: baseline; gap: 7px; }
.result-label { color: var(--muted); font-size: .82rem; }
.result strong { color: var(--green); font-size: 1.8rem; }
.out-of { color: var(--muted); }
.message { min-height: 24px; margin: 0; padding: 0 42px 20px; color: #c35353; font-size: .88rem; }
footer { padding: 20px; text-align: center; color: #8a92a5; font-size: .78rem; }
@media (max-width: 680px) { .page-shell { padding-top: 20px; } .quiz-header, .questions { padding-left: 22px; padding-right: 22px; } .options { grid-template-columns: 1fr; margin-left: 0; } .actions { padding: 22px; align-items: flex-start; flex-direction: column-reverse; } .message { padding-left: 22px; padding-right: 22px; } }

application.javascript:
const form = document.getElementById('quiz-form');
const scoreElement = document.querySelector('[data-testid="quiz-score"]');
const message = document.getElementById('message');
const answers = { q1: 'mars', q2: 'pacific', q3: 'six' };

form.addEventListener('submit', (event) => {
  event.preventDefault();
  const data = new FormData(form);
  const unanswered = ['q1', 'q2', 'q3'].filter((name) => !data.get(name));

  if (unanswered.length) {
    message.textContent = 'Please choose one answer for every question.';
    scoreElement.textContent = '—';
    scoreElement.removeAttribute('data-score');
    return;
  }

  let score = 0;
  Object.entries(answers).forEach(([question, answer]) => {
    if (data.get(question) === answer) score += 1;
  });
  scoreElement.textContent = String(score);
  scoreElement.setAttribute('data-score', String(score));
  message.textContent = score === 3 ? 'Perfect score — excellent work!' : 'Nice try! You can change your answers and submit again.';
});

form.addEventListener('change', () => {
  message.textContent = '';
});
